WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true AND ( ( true AND ( "s"."id" = $1 ) ) ) AND ( ( true ) ) ) ) ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "c1"."j" AS "articles" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" ) AS "%")) ORDER BY "t1"."id" ASC NULLS LAST ), '[]') AS "j" FROM ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND "s"."author_id" = "t0"."id" AND ( ( true AND ( ( true ) ) AND ( ( true ) ) ) ) ORDER BY "s"."id" ASC NULLS LAST LIMIT 0 ) AS "t1" ) AS "c1" ON true )
